// 1. Input Validation and Fault Latching
int fault = 0;

// Check enable
if (ep_input.enable != 0 && ep_input.enable != 1) {
    fault = 1;
}

// Check vectors non-null and finite
if (!fault && (ep_input.position_eci_m == NULL || ep_input.sun_direction_eci == NULL)) {
    fault = 1;
} else if (!fault && (!adcs_is_finite_vec3(ep_input.position_eci_m) || !adcs_is_finite_vec3(ep_input.sun_direction_eci))) {
    fault = 1;
}

// Check radius positive
if (!fault && (ep_config.earth_radius_m <= 0.0)) {
    fault = 1;
}

// Check counters in 1..100
if (!fault && (ep_config.recovery_cycles < 1 || ep_config.recovery_cycles > 100 || 
               ep_config.warmup_cycles < 1 || ep_config.warmup_cycles > 100)) {
    fault = 1;
}

// Check battery SOC and thresholds in [0,1] and off <= on
if (!fault && (!isfinite(ep_input.battery_soc) || ep_input.battery_soc < 0.0 || ep_input.battery_soc > 1.0)) {
    fault = 1;
} else if (!fault && (!isfinite(ep_config.payload_on_soc) || ep_config.payload_on_soc < 0.0 || ep_config.payload_on_soc > 1.0)) {
    fault = 1;
} else if (!fault && (!isfinite(ep_config.payload_off_soc) || ep_config.payload_off_soc < 0.0 || ep_config.payload_off_soc > 1.0)) {
    fault = 1;
} else if (!fault && (ep_config.payload_off_soc > ep_config.payload_on_soc)) {
    fault = 1;
}

if (fault) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

// 2. Eclipse Geometry Calculation
adcs_vec3_t sun_dir_norm;
adcs_status_t norm_status = adcs_vec3_normalize(ep_input.sun_direction_eci, 1e-12, &sun_dir_norm);
if (norm_status != ADCS_OK) {
     ep_output.mode = EP_FAULT;
     ep_output.elapsed = 0;
     ep_output.payload_on = 0;
     ep_output.heater_on = 0;
     ep_output.axial_m = 0.0;
     ep_output.cross_track_m = 0.0;
     return;
}

double axial_m = adcs_vec3_dot(ep_input.position_eci_m, &sun_dir_norm);
adcs_vec3_t cross_vec = adcs_vec3_cross(ep_input.position_eci_m, &sun_dir_norm);
double cross_track_m = adcs_vec3_norm(&cross_vec);

// 3. Eclipse Detection
int in_eclipse = (axial_m < 0.0) && (cross_track_m < ep_config.earth_radius_m);

// Initialize output fields defaults
ep_output.axial_m = axial_m;
ep_output.cross_track_m = cross_track_m;
ep_output.payload_on = 0;
ep_output.heater_on = 0;

// 4. State Machine Logic
ep_mode_t prev_mode = ep_state.mode;
ep_output.mode = prev_mode;

if (in_eclipse) {
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0;
    ep_output.heater_on = 1;
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0;
} else {
    // Sunlight phases
    switch (prev_mode) {
        case EP_ECLIPSE:
            ep_output.mode = EP_RECOVERY;
            ep_state.mode = EP_RECOVERY;
            ep_state.elapsed = 1;
            break;

        case EP_RECOVERY:
            ep_state.elapsed++;
            if (ep_state.elapsed >= ep_config.recovery_cycles) {
                ep_output.mode = EP_WARMUP;
                ep_state.mode = EP_WARMUP;
                ep_state.elapsed = 1;
            } else {
                ep_output.mode = EP_RECOVERY;
            }
            break;

        case EP_WARMUP:
            ep_state.elapsed++;
            if (ep_state.elapsed >= ep_config.warmup_cycles) {
                if (ep_input.battery_soc >= ep_config.payload_on_soc) {
                    ep_output.mode = EP_SUN;
                    ep_output.payload_on = 1;
                    ep_state.mode = EP_SUN;
                    ep_state.elapsed = 0;
                } else {
                    ep_output.mode = EP_LOADWAIT;
                    ep_output.payload_on = 0;
                    ep_state.mode = EP_LOADWAIT;
                    ep_state.elapsed = 0;
                }
            } else {
                ep_output.mode = EP_WARMUP;
                ep_output.payload_on = 0;
            }
            break;

        case EP_LOADWAIT:
            if (ep_input.battery_soc >= ep_config.payload_on_soc) {
                ep_output.mode = EP_SUN;
                ep_output.payload_on = 1;
                ep_state.mode = EP_SUN;
                ep_state.elapsed = 0;
            } else {
                ep_output.mode = EP_LOADWAIT;
                ep_output.payload_on = 0;
                ep_state.elapsed++;
            }
            break;

        case EP_LOADSHED:
            if (ep_input.battery_soc >= ep_config.payload_on_soc) {
                ep_output.mode = EP_SUN;
                ep_output.payload_on = 1;
                ep_state.mode = EP_SUN;
                ep_state.elapsed = 0;
            } else {
                ep_output.mode = EP_LOADSHED;
                ep_output.payload_on = 0;
                ep_state.elapsed++;
            }
            break;

        case EP_SUN:
            if (ep_input.battery_soc < ep_config.payload_off_soc) {
                ep_output.mode = EP_LOADSHED;
                ep_output.payload_on = 0;
                ep_state.mode = EP_LOADSHED;
                ep_state.elapsed = 0;
            } else {
                ep_output.mode = EP_SUN;
                ep_output.payload_on = 1;
                ep_state.elapsed++;
            }
            break;

        case EP_FAULT:
        default:
            ep_output.mode = EP_FAULT;
            break;
    }
    ep_output.elapsed = ep_state.elapsed;
}

// Handle Disabled override
if (ep_input.enable == 0) {
    ep_output.mode = EP_SUN;
    ep_output.payload_on = 0;
    ep_output.elapsed = 0;
    ep_state.mode = EP_SUN;
    ep_state.elapsed = 0;
}

